import{c as e,Q as t,j as o,m as r}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"Anthropic Workshop: Building LLMs from Scratch + Claude Code Pro Tips","description":"","frontmatter":{"url":"https://x.com/maarcoofdezz/status/2070554671450660972","title":"Anthropic Workshop: Building LLMs from Scratch + Claude Code Pro Tips","author":"@maarcoofdezz","archived":"2026-06-27T00:00:00.000Z","duration_p1":"01:44:17","duration_p2":"27:15","duration_total":"02:11:32","handle":"@maarcoofdezz","parts":2,"published":"2026-06-26T00:00:00.000Z","subtitle_lang":"en","type":"playlist"},"headers":[],"relativePath":"research/tweets/2026-06-26-maarcoofdezz-2070554671450660972.md","filePath":"research/tweets/2026-06-26-maarcoofdezz-2070554671450660972.md","lastUpdated":1785909234000}'),l={name:"research/tweets/2026-06-26-maarcoofdezz-2070554671450660972.md"};function i(n,a,s,d,c,p){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="anthropic-workshop-building-llms-from-scratch-claude-code-pro-tips-—-maarcoofdezz" tabindex="-1">Anthropic Workshop: Building LLMs from Scratch + Claude Code Pro Tips — @maarcoofdezz <a class="header-anchor" href="#anthropic-workshop-building-llms-from-scratch-claude-code-pro-tips-—-maarcoofdezz" aria-label="Permalink to &quot;Anthropic Workshop: Building LLMs from Scratch + Claude Code Pro Tips — @maarcoofdezz&quot;">​</a></h1><p><strong>來源</strong>: <a href="https://x.com/maarcoofdezz/status/2070554671450660972" target="_blank" rel="noreferrer">https://x.com/maarcoofdezz/status/2070554671450660972</a><strong>作者</strong>: @maarcoofdezz <strong>發布日期</strong>: 2026-06-26 <strong>收錄日期</strong>: 2026-06-27 <strong>時長</strong>: Part 1: 01:44:17 / Part 2: 27:15（合計 02:11:32） <strong>語言</strong>: English（含 Spanish 口譯）</p><hr><h2 id="核心摘要" tabindex="-1">核心摘要 <a class="header-anchor" href="#核心摘要" aria-label="Permalink to &quot;核心摘要&quot;">​</a></h2><blockquote><p>本 playlist 收錄 Anthropic 工作坊兩支影片：Part 1 為一堂從頭到尾解構 LLM 訓練流程的技術講座，涵蓋架構、訓練資料、評估、SFT 與 RLHF；Part 2 為 Claude Code 創作者 Boris 親授的實用操作心法。</p></blockquote><h3 id="part-1-building-llms-01-44-17" tabindex="-1">Part 1：Building LLMs（01:44:17） <a class="header-anchor" href="#part-1-building-llms-01-44-17" aria-label="Permalink to &quot;Part 1：Building LLMs（01:44:17）&quot;">​</a></h3><ul><li>LLM 本質是自迴歸語言模型（autoregressive），每次預測下一個 token 的機率分佈；輸出向量維度等於 vocabulary size</li><li>Transformer 架構三步驟：token embedding → multi-layer transformer → linear projection → softmax；現代模型幾乎全採此框架</li><li>訓練資料規模從 150B tokens（早期學術）增至 15T tokens（當前主流），主要來源為 Common Crawl、Wikipedia、GitHub、arXiv 等</li><li>規模法則（Chinchilla）：在固定 compute budget 下，模型參數量與訓練 token 數應約 1:20 比例；考慮推理成本後業界偏好較小模型配更多資料（約 1:150）</li><li>訓練一個 LLaMA 級模型實際成本估算：H100 GPU 費用約 $52M + 人力 $25M = 總計約 $75M；碳排放約 4,000 噸 CO₂ 當量（≈ 2,000 趟 JFK↔London 來回）</li><li>SFT（Supervised Fine-Tuning）：以少量高品質人工標注 Q&amp;A（5K–50K 筆）對預訓練模型進行微調；Alpaca 示範用 52K LLM 生成指令資料即可顯著改善指令跟隨能力</li><li>RLHF：以人類偏好資料（規模達 1M 筆）訓練獎勵模型後再強化學習；人類標注員自身一致率僅約 66%，LLM-as-judge 在成本與一致性上均優於人類標注</li></ul><h3 id="part-2-claude-code-實用心法-27-15" tabindex="-1">Part 2：Claude Code 實用心法（27:15） <a class="header-anchor" href="#part-2-claude-code-實用心法-27-15" aria-label="Permalink to &quot;Part 2：Claude Code 實用心法（27:15）&quot;">​</a></h3><ul><li>Claude Code 定位為<strong>完全自主代理</strong>（fully agentic），不是行補全工具；適合完整功能開發、bug 修復、跨檔案重構</li><li>善用 Codebase Q&amp;A：直接問 Claude 程式碼歷史（「為何這個函式有 15 個參數？」），Claude 可翻 git 歷史自行調查</li><li>最佳化迭代迴路：給 Claude 能驗證自身工作的工具（unit tests、Puppeteer 截圖、iOS Simulator），讓它自動迭代而非等待人工確認</li><li>CLAUDE.md 是最重要的配置檔：放 bash 指令、MCP 工具、架構決策，checkin 進 git 與團隊共享；nested CLAUDE.md 可套用到特定目錄</li><li>企業功能：enterprise policy 檔可全公司統一設定自動允許/禁止指令清單、MCP server 清單，一次配置全員共享</li><li>快捷鍵：<code>Shift+Tab</code> 進入 auto-accept 模式（自動接受編輯，bash 指令仍需確認）</li><li>多模態：可直接拖拉圖片進 terminal（設計稿→直接實作 UI）</li><li>Boris 對 CLI 而非 IDE 的選擇原因：① 公司內部 IDE 多元，terminal 是最大公約數 ② 模型進步速度讓 IDE UI 層可能很快過時</li></ul><hr><h2 id="part-1-整理版-building-llms-—-01-44-17" tabindex="-1">Part 1 整理版（Building LLMs — 01:44:17） <a class="header-anchor" href="#part-1-整理版-building-llms-—-01-44-17" aria-label="Permalink to &quot;Part 1 整理版（Building LLMs — 01:44:17）&quot;">​</a></h2><h3 id="_1-什麼是-llm-00-00–08-00" tabindex="-1">1. 什麼是 LLM（00:00–08:00） <a class="header-anchor" href="#_1-什麼是-llm-00-00–08-00" aria-label="Permalink to &quot;1. 什麼是 LLM（00:00–08:00）&quot;">​</a></h3><p>講師以 ChatGPT、Claude、Gemini、Llama 等為例介紹大語言模型（Large Language Models）。今天課程的目標是一個概覽：從架構、資料、評估到對齊，走完整個訓練管線。</p><p>核心定義：LLM 是<strong>自迴歸語言模型</strong>（autoregressive language model）。做的事情非常單純——給定一段文字，預測下一個 token 的機率分佈。所有的「聊天」「推理」「coding」能力，都是這一個簡單目標訓練出來的湧現結果。</p><h3 id="_2-架構基礎-transformer-08-00–21-00" tabindex="-1">2. 架構基礎：Transformer（08:00–21:00） <a class="header-anchor" href="#_2-架構基礎-transformer-08-00–21-00" aria-label="Permalink to &quot;2. 架構基礎：Transformer（08:00–21:00）&quot;">​</a></h3><p>自迴歸 LLM 的計算流程：</p><ol><li><strong>Tokenization</strong>：將文字切成 tokens（通常是 subword 單位，如 BPE）</li><li><strong>Embedding</strong>：每個 token → 向量表徵（embedding vector）</li><li><strong>Transformer Layers</strong>：多層 self-attention + FFN，對整個 context 產生聯合表徵</li><li><strong>Linear + Softmax</strong>：投影到 vocabulary size 維度，得到下一 token 的機率分佈</li></ol><p>Vocabulary size（詞彙表大小）同時也是模型最後一層的輸出維度，通常在 32K–128K 之間。Tokenization 設計對模型表現影響顯著，不同 tokenizer 會導致 perplexity 不可比較。</p><h3 id="_3-評估指標與-benchmark-21-00–39-00" tabindex="-1">3. 評估指標與 Benchmark（21:00–39:00） <a class="header-anchor" href="#_3-評估指標與-benchmark-21-00–39-00" aria-label="Permalink to &quot;3. 評估指標與 Benchmark（21:00–39:00）&quot;">​</a></h3><p><strong>Perplexity</strong>：訓練過程最核心的指標，等同於模型對「下一 token」的驚訝程度。數字越低越好。現在已不用於學術排名（因為依賴 tokenizer 與測試集選擇），但訓練期間仍是最重要的開發信號。</p><p><strong>主流 Benchmark</strong>：</p><ul><li><strong>HELM</strong>（Stanford）：涵蓋問答、摘要、毒性偵測等多個維度</li><li><strong>MMLU</strong>（Massive Multitask Language Understanding）：覆蓋大學物理、醫學、天文等 57 個知識領域的選擇題，是最常用的能力評估</li><li><strong>HuggingFace Open LLM Leaderboard</strong>：開源模型的公開排行榜</li></ul><p>評估方式：給模型四個選項（A/B/C/D），比較各選項的生成機率或讓模型直接輸出字母。</p><h3 id="_4-訓練資料與規模法則-39-00–55-00" tabindex="-1">4. 訓練資料與規模法則（39:00–55:00） <a class="header-anchor" href="#_4-訓練資料與規模法則-39-00–55-00" aria-label="Permalink to &quot;4. 訓練資料與規模法則（39:00–55:00）&quot;">​</a></h3><p><strong>訓練資料演進</strong>：</p><ul><li>早期（學術規模）：~150B tokens，約 800 GB</li><li>當前主流：~15T tokens，~100 TB</li></ul><p>主要來源：Common Crawl（網頁爬取，須大量過濾）、arXiv、PubMed、Wikipedia、GitHub、Stack Exchange、書籍等。「The Pile」是代表性的學術開源資料集，揭示了典型的資料分佈比例。</p><p><strong>Chinchilla 規模法則</strong>（Hoffmann et al.）：在固定 compute budget 下，模型參數量與訓練 token 數應維持約 <strong>1:20</strong> 的比例——這讓業界從「瘋狂堆參數」轉向「加大資料量」的策略。</p><p><strong>Bitter Lesson</strong>（Richard Sutton, 2019）：AI 歷史一再表明，長期贏家總是擴展計算力，而非精心設計人工 inductive bias。</p><p><strong>推理成本考量</strong>：若把推理成本納入，每個 token 的參數比應提高到約 1:150（更小的模型，更多的資料），因為小模型長期運行成本更低。</p><h3 id="_5-訓練成本與碳排放-55-00–01-02-00" tabindex="-1">5. 訓練成本與碳排放（55:00–01:02:00） <a class="header-anchor" href="#_5-訓練成本與碳排放-55-00–01-02-00" aria-label="Permalink to &quot;5. 訓練成本與碳排放（55:00–01:02:00）&quot;">​</a></h3><p>以訓練一個 LLaMA 規模模型為例的成本估算：</p><ul><li><strong>GPU 費用</strong>：H100 租用約 $2/小時，訓練需 ~2,600 萬 GPU 小時 → ~$52M</li><li><strong>人力費用</strong>：50 位工程師 × $500K/年 → $25M</li><li><strong>總計</strong>：約 <strong>$75M</strong></li></ul><p><strong>碳排放</strong>：約 4,000 噸 CO₂ 當量，相當於 2,000 趟 JFK↔London 來回機票——不可忽視，但在業界尚不是決策首要考量。</p><h3 id="_6-對齊與微調-sft-01-02-00–01-15-00" tabindex="-1">6. 對齊與微調：SFT（01:02:00–01:15:00） <a class="header-anchor" href="#_6-對齊與微調-sft-01-02-00–01-15-00" aria-label="Permalink to &quot;6. 對齊與微調：SFT（01:02:00–01:15:00）&quot;">​</a></h3><p><strong>為何 Pre-training 不夠用</strong>：預訓練模型學的是「預測網路上的文字」，但網路上的文字不是「問答」，也不包含「禁止有害輸出」的行為。SFT 就是用來解決這個落差。</p><p><strong>Supervised Fine-Tuning（SFT）</strong>：在少量（5K–50K 筆）人工標注的 (instruction, response) 對上微調。模型已有語言能力，只需學習「回答問題」的格式與「遵守安全規則」的行為。</p><p><strong>Alpaca 案例</strong>（Stanford, 2023）：用 175 筆人工 Q&amp;A 加上 GPT-3（text-davinci-003），讓它生成 52,000 筆指令資料，再微調 LLaMA-7B。結果得到一個指令跟隨能力顯著改善的 Alpaca-7B，且成本極低。這示範了「LLM 生成合成資料用於 SFT」的可行性。</p><p>合成資料的風險：若反覆用同一分佈的 LLM 生成資料，模型會過擬合到生成分佈，而非學到更廣的能力（model collapse 問題）。</p><h3 id="_7-rlhf-與-llm-as-judge-01-25-00–01-44-17" tabindex="-1">7. RLHF 與 LLM-as-Judge（01:25:00–01:44:17） <a class="header-anchor" href="#_7-rlhf-與-llm-as-judge-01-25-00–01-44-17" aria-label="Permalink to &quot;7. RLHF 與 LLM-as-Judge（01:25:00–01:44:17）&quot;">​</a></h3><p><strong>RLHF 的動機</strong>：SFT 訓練的是「模仿最佳答案」，但很多情況下很難定義什麼是「最佳答案」。人類偏好（哪個回答更好？）比絕對標注更容易收集。</p><p><strong>人類標注的挑戰</strong>：</p><ul><li>標注員自身一致率僅約 <strong>66%</strong>（二元選擇題）</li><li>收集成本高（Mechanical Turk 約 $300/千筆）</li><li>標注員分佈偏差（annotator distribution shift）</li><li>勞動倫理問題（標注員需接觸大量有毒內容）</li></ul><p><strong>LLM-as-Judge</strong>：用最強的現有 LLM 替代人類標注。實驗顯示，頂尖 LLM 的偏好一致性可超過人類（&gt;66%），且成本大幅降低。現在業界普遍採用「人類 + LLM 混合標注」的方式。</p><p><strong>LoRA vs 全量微調</strong>：業界 SFT/RLHF 通常更新全部權重；開源社群常用 LoRA（僅為每層添加低秩矩陣差值），以減少計算/記憶體成本，但表達能力有所犧牲。</p><hr><h2 id="part-2-整理版-claude-code-實用心法-—-27-15" tabindex="-1">Part 2 整理版（Claude Code 實用心法 — 27:15） <a class="header-anchor" href="#part-2-整理版-claude-code-實用心法-—-27-15" aria-label="Permalink to &quot;Part 2 整理版（Claude Code 實用心法 — 27:15）&quot;">​</a></h2><blockquote><p>主講：Boris（Claude Code 創作者，Anthropic MTS）</p></blockquote><h3 id="_1-claude-code-是什麼-00-00–04-50" tabindex="-1">1. Claude Code 是什麼（00:00–04:50） <a class="header-anchor" href="#_1-claude-code-是什麼-00-00–04-50" aria-label="Permalink to &quot;1. Claude Code 是什麼（00:00–04:50）&quot;">​</a></h3><p>Claude Code 不是「行補全工具」。過去兩代 AI 助手（GitHub Copilot 等）設計目標是補全幾行程式碼，Claude Code 的目標是<strong>完全自主代理（fully agentic）</strong>：</p><ul><li>建立整個功能（features）</li><li>撰寫完整函式、完整檔案</li><li>同時修復整個 bug 並理解影響範圍</li></ul><p>Claude Code 不依賴 IDE 索引——啟動即可用，無需等待 indexing。</p><h3 id="_2-codebase-q-a-04-50–11-00" tabindex="-1">2. Codebase Q&amp;A（04:50–11:00） <a class="header-anchor" href="#_2-codebase-q-a-04-50–11-00" aria-label="Permalink to &quot;2. Codebase Q&amp;A（04:50–11:00）&quot;">​</a></h3><p><strong>最有效的起手式</strong>：用 Claude Code 問問題，而不是直接要它做事。</p><p>範例：</p><ul><li>「為什麼這個函式有 15 個參數？那些奇怪的參數名是怎麼來的？」</li><li>「這個 class 最初是什麼時候引入的，為什麼？」</li></ul><p>Claude Code 可以翻閱 git 歷史、閱讀 commit message、追蹤 PR，提供有脈絡的解釋——這是過去要花一週讀文件才能理解的知識。</p><p><strong>語音輸入技巧</strong>：macOS 的系統級 Dictation 功能可以對 Claude Code 說話，特別適合在「講英文比打字更快」的情況下輸入長段描述。</p><h3 id="_3-工具-迭代迴路-11-00–17-00" tabindex="-1">3. 工具 + 迭代迴路（11:00–17:00） <a class="header-anchor" href="#_3-工具-迭代迴路-11-00–17-00" aria-label="Permalink to &quot;3. 工具 + 迭代迴路（11:00–17:00）&quot;">​</a></h3><p>Claude Code 最強大的使用方式：<strong>給它一個能驗證自身工作的工具</strong>。</p><ul><li><strong>Unit tests</strong>：讓 Claude Code 自己跑測試、看結果、迭代修復</li><li><strong>Puppeteer MCP</strong>：Web UI 截圖後讓它看圖自動修正樣式</li><li><strong>iOS Simulator 截圖</strong>：App UI 迭代</li></ul><p>操作建議：</p><ol><li>如果你確定 Claude 走在正確的路上，按 <code>Shift+Tab</code> 進入 <strong>auto-accept 模式</strong>（編輯自動接受，bash 指令仍需手動確認）</li><li>給 Claude 明確的工作流程指示：想要它直接動手還是先規劃、先確認？</li></ol><h3 id="_4-claude-md-與記憶管理-17-00–18-30" tabindex="-1">4. CLAUDE.md 與記憶管理（17:00–18:30） <a class="header-anchor" href="#_4-claude-md-與記憶管理-17-00–18-30" aria-label="Permalink to &quot;4. CLAUDE.md 與記憶管理（17:00–18:30）&quot;">​</a></h3><p><strong>CLAUDE.md 的角色</strong>：Claude Code 的「永久記憶」——自動載入到每個 session 的 context 前綴。</p><p>放什麼進去：</p><ul><li>常用 bash 指令（test runner、build 指令）</li><li>MCP 工具說明</li><li>重要架構決策</li><li>關鍵檔案路徑</li></ul><p><strong>建議</strong>：CLAUDE.md 要 check in 進 git，與整個團隊共享——一人維護，全員受益。</p><p><strong><code>/memory</code> 指令</strong>：查看目前所有載入的 memory 檔案來源（enterprise policy、user 個人設定、project CLAUDE.md、nested 目錄 CLAUDE.md）；<code>#</code> 語法可立即記錄到指定 memory 檔案。</p><h3 id="_5-快捷鍵備忘-18-30–19-30" tabindex="-1">5. 快捷鍵備忘（18:30–19:30） <a class="header-anchor" href="#_5-快捷鍵備忘-18-30–19-30" aria-label="Permalink to &quot;5. 快捷鍵備忘（18:30–19:30）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>按鍵</th><th>功能</th></tr></thead><tbody><tr><td><code>Shift+Tab</code></td><td>切換 auto-accept 模式（自動接受所有編輯）</td></tr></tbody></table><p>Terminal UI 的限制使得這些快捷鍵不易被發現，Boris 建議定期翻閱文件。</p><h3 id="_6-企業功能與共享配置-19-30–26-00" tabindex="-1">6. 企業功能與共享配置（19:30–26:00） <a class="header-anchor" href="#_6-企業功能與共享配置-19-30–26-00" aria-label="Permalink to &quot;6. 企業功能與共享配置（19:30–26:00）&quot;">​</a></h3><p><strong>Enterprise Policy 檔</strong>：</p><ul><li>可全公司統一設定「哪些 bash 指令自動允許」（無需每次確認）</li><li>可封鎖特定 URL 永遠不被 fetch</li><li>可預先配置 MCP server 清單，員工第一次執行時自動提示安裝</li></ul><p><strong>Puppeteer MCP 實例</strong>：Anthropic 內部 apps repo 的 <code>.mcp.json</code> 預先配置 Puppeteer，所有工程師在該 repo 跑 Claude Code 時自動能用截圖迭代 UI，無需手動安裝。</p><h3 id="_7-q-a-精選-26-00–27-15" tabindex="-1">7. Q&amp;A 精選（26:00–27:15） <a class="header-anchor" href="#_7-q-a-精選-26-00–27-15" aria-label="Permalink to &quot;7. Q&amp;A 精選（26:00–27:15）&quot;">​</a></h3><p><strong>Q：Claude Code 是否支援多模態（圖片）？</strong> A：完全支援。可以拖拉圖片進 terminal，或從剪貼板貼上。Boris 常用方式：把設計稿截圖拖進去，說「implement this」，同時開 dev server 讓它截圖自動對比。</p><p><strong>Q：為什麼做 CLI 而非 IDE？</strong> A：兩個原因：① Anthropic 內部工程師用很多種 IDE（VS Code、Zed、Xcode、VIM、EMACS），terminal 是最大公約數；② 模型進步如此之快，Boris 預期年底前 IDE 的作用可能大幅改變，不想過度投資在 UI 抽象層上。</p><hr><h2 id="原始逐字稿-時間戳索引" tabindex="-1">原始逐字稿（時間戳索引） <a class="header-anchor" href="#原始逐字稿-時間戳索引" aria-label="Permalink to &quot;原始逐字稿（時間戳索引）&quot;">​</a></h2><h3 id="part-1-building-llms" tabindex="-1">Part 1（Building LLMs） <a class="header-anchor" href="#part-1-building-llms" aria-label="Permalink to &quot;Part 1（Building LLMs）&quot;">​</a></h3><p><code>&lt;details&gt;</code><code>&lt;summary&gt;</code>展開查看 Part 1 完整逐字稿（1,601 segments）<code>&lt;/summary&gt;</code></p><p><em>原始轉錄檔：<code>/tmp/claude-scratch/out/maarcoofdezz-p1.txt</code>（Whisper small model，detected lang: es）</em></p><p><code>&lt;/details&gt;</code></p><h3 id="part-2-claude-code-pro-tips-by-boris" tabindex="-1">Part 2（Claude Code Pro Tips by Boris） <a class="header-anchor" href="#part-2-claude-code-pro-tips-by-boris" aria-label="Permalink to &quot;Part 2（Claude Code Pro Tips by Boris）&quot;">​</a></h3><p><code>&lt;details&gt;</code><code>&lt;summary&gt;</code>展開查看 Part 2 完整逐字稿（395 segments）<code>&lt;/summary&gt;</code></p><p><em>原始轉錄檔：<code>/tmp/claude-scratch/out/maarcoofdezz-p2.txt</code>（Whisper base model，detected lang: es）</em></p><p><code>&lt;/details&gt;</code></p>',89)])])}const g=e(l,[["render",i]]);export{h as __pageData,g as default};
